window.kbParts["entries-4762903c837954b1"] = {"nodes":{"s-a7ce466b25f8ea1b":{"sources":[{"id":"7a985b326fc58141","label":"计算现期比重","topic":"资料分析方法","category":"非时政","text":"圈出题目所求的部分和总体，核对时间、单位、统计范围，再用部分量除以总体量。题目列出几个不重叠的部分时，先加总分子。","source":{"doc":"ecade1ff5af69283232e","first":38,"last":38,"file":"ecade1ff5af69283232e.pdf","page":38},"basis":"据题目与解析整理"}]},"s-rates":{"sources":[{"id":"e749694b526d0e5e","label":"比较同比增速","topic":"资料分析方法","category":"非时政","text":"先圈出同一指标的现期和上年同期。用增长量除以上年同期量，比较各项增长率。只有现期量和增长量时，先相减求出上年同期量。","source":{"doc":"e1792c53900a45f1b9fa","first":38,"last":38,"file":"e1792c53900a45f1b9fa.pdf","page":38},"basis":"据题目与解析整理"}]}}};
